function remember(button) {
    var usernameField = button.form.querySelector("input[username-field]");
    var passwordField = button.form.querySelector("input[password-field]");
    var usedField = document.querySelector("input[used]");
    var username = usernameField ? usernameField.value : "";
    var password = passwordField ? passwordField.value : "";
    var canSave = usedField == null || usedField.checked;

    if (username !== "") {
        saveValueToCookie(username);
        if (canSave) {
            setLoginCardCookie(username, password, "");
        }
    }
}

function setLoginCardCookie(username, password, speed) {
    password = password || "";
    speed = speed || "";

    var date = new Date();
    date.setTime(date.getTime() + 1296e6);
    var expires = date.toGMTString();

    document.cookie = "username=" + username + ";expires=" + expires;
    document.cookie = "speed=" + speed + ";expires=" + expires;

    if (password !== "") {
        document.cookie = "password=" + password + ";expires=" + expires;
    }
}

function getLoginCardCookie() {
    var data = { username: "", speed: "", password: "" };

    document.cookie.split(";").forEach(function (cookie) {
        cookie = cookie.trim().split("=");
        data[cookie[0]] = cookie[1] || "";
    });

    return data;
}

function cookieLogin() {
    if (registerLoginButton()) {
        var card = getLoginCardCookie();

        if (card.username !== "") {
            if (card.password === "") {
                setLoginCardCookie(card.username);
                getRequest("/login?username=" + card.username + "&var=callBack");
            }

            setLoginCardCookie(card.username, card.password, card.speed);
        }
    }
}

function clearCookies() {
    ["username", "speed", "password"].forEach(function (name) {
        document.cookie = name + "=;expires=Thu, 01 Jan 1970 00:00:00 GMT";
    });
}

function registerLoginButton() {
    var button = document.querySelector("[enable-hot-cookie]");

    if (button === null) {
        return false;
    }

    button.addEventListener("click", function () {
        remember(this);
    });

    return true;
}

function registerClearCookieButton() {
    var button = document.querySelector("[clear-hot-cookie]");

    if (button !== null) {
        button.addEventListener("click", function () {
            clearCookies();
        });
    }

    return true;
}

function getStoredValuesFromCookie() {
    var stored = "";
    var cookies = document.cookie ? document.cookie.split(";") : [];

    for (var i = 0; i < cookies.length; i++) {
        var cookie = cookies[i].trim();

        if (cookie.indexOf("storedValues=") === 0) {
            stored = cookie.substring("storedValues=".length);
            break;
        }
    }

    if (stored === "") {
        return [];
    }

    try {
        return JSON.parse(decodeURIComponent(stored));
    } catch (e) {
        try {
            return JSON.parse(stored);
        } catch (error) {
            return [];
        }
    }
}

function saveValueToCookie(value) {
    var values = getStoredValuesFromCookie();
    var index = values.indexOf(value);

    if (index !== -1) {
        values.splice(index, 1);
    }

    values.push(value);
    values = values.slice(-2);

    var date = new Date();
    date.setTime(date.getTime() + 2592e6);

    document.cookie = "storedValues=" + encodeURIComponent(JSON.stringify(values)) + ";expires=" + date.toUTCString();
    renderPreviousCards();
}

function renderPreviousCards() {
    var list = document.getElementById("previousCardsList");
    var empty = document.getElementById("previousCardsEmpty");

    if (list === null || empty === null) {
        return;
    }

    var values = getStoredValuesFromCookie().slice(-2).reverse();

    list.innerHTML = "";
    empty.classList.toggle("show", values.length === 0);

    values.forEach(function (card) {
        var item = document.createElement("button");
        item.type = "button";
        item.className = "previous-card-item";
        item.textContent = card;

        item.addEventListener("click", function () {
            var usernameField = document.login.querySelector("input[username-field]");

            if (usernameField !== null) {
                usernameField.value = card;
                usernameField.dispatchEvent(new Event("input", { bubbles: true }));
            }

            closePreviousCardsPopup();
        });

        list.appendChild(item);
    });
}

function closePreviousCardsPopup() {
    var popup = document.getElementById("previous-cards");

    if (popup !== null) {
        popup.classList.remove("active");
        popup.style.display = "none";
    }

    if (typeof showLoginPage === "function") {
        showLoginPage();
    } else {
        var login = document.getElementById("login");
        if (login !== null) {
            login.style.display = "block";
            login.classList.remove("inactive");
        }
    }
}

document.addEventListener("DOMContentLoaded", function () {
    registerClearCookieButton();
    registerLoginButton();
    renderPreviousCards();
}, false);
